export function createDesignController(root,hooks){
const document={getElementById:id=>{const node=root.getElementById(id);return node?.type==='number'?new Proxy(node,{get:(target,key)=>{if(key==='value')return target.value||target.placeholder;const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;},set:(target,key,value)=>Reflect.set(target,key,value,target)}):node;},querySelectorAll:selector=>root.querySelectorAll(selector),createElement:tag=>globalThis.document.createElement(tag)},window={};let toastTimer;const setTimeout=(fn,ms)=>{clearTimeout(toastTimer);toastTimer=globalThis.setTimeout(fn,ms);return toastTimer;};

        let lastFocusedInput = document.getElementById('input-msg');
        let currentSeverity = 'important';

        // Switch View Pages
        function switchView(viewName) {
            const overview = document.getElementById('view-overview');
            const detail = document.getElementById('view-detail');
            const tabOverview = document.getElementById('tab-overview');
            const tabDetail = document.getElementById('tab-detail');

            if (viewName === 'overview') {
                overview.classList.remove('hidden');
                detail.classList.add('hidden');
                tabOverview.className = "px-3 py-1 rounded-full font-bold text-[10px] bg-emerald-400 text-slate-950 transition-all";
                tabDetail.className = "px-3 py-1 rounded-full font-bold text-[10px] text-gray-400 hover:text-gray-200 transition-all";
            } else {
                detail.classList.remove('hidden');
                overview.classList.add('hidden');
                tabDetail.className = "px-3 py-1 rounded-full font-bold text-[10px] bg-emerald-400 text-slate-950 transition-all";
                tabOverview.className = "px-3 py-1 rounded-full font-bold text-[10px] text-gray-400 hover:text-gray-200 transition-all";
            }
        }

        // Toggle Master Notifications
        function toggleMasterNotifications(enabled) {
            const badge = document.getElementById('master-status-badge');
            const label = document.getElementById('master-action-label');
            const icon = document.getElementById('master-power-icon');

            if (enabled) {
                badge.className = "px-2 py-0.5 rounded-md bg-emerald-400/20 text-emerald-400 font-mono font-bold text-[10px] uppercase";
                badge.innerText = "ACTIVE";
                label.innerText = "Notifications Enabled";
                label.className = "px-3 py-1.5 rounded-full bg-[#25282e] text-emerald-400 border border-[#282a30] font-bold text-[11px] hidden sm:inline-block";
                icon.className = "w-11 h-11 rounded-2xl bg-emerald-400 text-slate-950 flex items-center justify-center font-bold text-lg shadow-lg emerald-glow shrink-0 transition-all";
                showToast("All notifications enabled");
            } else {
                badge.className = "px-2 py-0.5 rounded-md bg-gray-700/40 text-gray-400 font-mono font-bold text-[10px] uppercase";
                badge.innerText = "MUTED";
                label.innerText = "Notifications Disabled";
                label.className = "px-3 py-1.5 rounded-full bg-[#151619] text-gray-500 border border-[#282a30] font-bold text-[11px] hidden sm:inline-block";
                icon.className = "w-11 h-11 rounded-2xl bg-[#151619] border border-[#282a30] text-gray-500 flex items-center justify-center font-bold text-lg shrink-0 transition-all";
                showToast("Notifications paused globally");
            }
        }

        // Toggle Devices Pills
        function toggleDevicePill(btn) {
            if (btn.classList.contains('active')) {
                btn.classList.remove('active', 'bg-emerald-400', 'text-slate-950', 'font-bold', 'shadow-md', 'border-emerald-400');
                btn.classList.add('bg-[#25282e]', 'border-[#282a30]', 'text-gray-400');
                const check = btn.querySelector('.fa-check');
                if (check) check.remove();
            } else {
                btn.classList.add('active', 'bg-emerald-400', 'text-slate-950', 'font-bold', 'shadow-md', 'border-emerald-400');
                btn.classList.remove('bg-[#25282e]', 'border-[#282a30]', 'text-gray-400');
                const checkIcon = document.createElement('i');
                checkIcon.className = 'fa-solid fa-check text-xs';
                btn.insertBefore(checkIcon, btn.firstChild);
            }
            
            const activeCount = document.querySelectorAll('.device-pill.active').length;
            document.getElementById('device-count').innerText = `${activeCount} Active`;
        }

        // Quiet hours toggle
        function toggleQuietHours(enabled) {
            const box = document.getElementById('quiet-inputs-box');
            if (enabled) {
                box.style.opacity = '1';
                box.style.pointerEvents = 'auto';
            } else {
                box.style.opacity = '0.3';
                box.style.pointerEvents = 'none';
            }
        }

        function setQuietMode(btn, mode) {
            document.querySelectorAll('.quiet-mode-btn').forEach(b => {
                b.className = "quiet-mode-btn py-1.5 rounded-lg text-gray-400 hover:text-gray-200 text-[11px] font-medium text-center transition-all";
            });
            btn.className = "quiet-mode-btn active py-1.5 rounded-lg bg-emerald-400 text-slate-950 font-bold text-[11px] text-center transition-all";
        }

        // Filter Matrix presets
        function filterPresets(btn, type) {
            document.querySelectorAll('.preset-btn').forEach(b => {
                b.className = "preset-btn px-3 py-1 rounded-lg text-gray-400 hover:text-gray-200 transition-all";
            });
            btn.className = "preset-btn active px-3 py-1 rounded-lg bg-emerald-400 text-slate-950 font-bold shadow";
            showToast(`Filter applied: ${type.toUpperCase()}`);
        }

        // Editor Functions
        function adjustValue(inputId, step) {
            const input = document.getElementById(inputId);
            let val = parseInt(input.value) || 0;
            const min = parseInt(input.min) || 0;
            const max = parseInt(input.max) || 999;
            input.value = Math.max(min, Math.min(max, val + step));
            updateCalculations();
        }

        function updateCalculations() {
            const delay = parseInt(document.getElementById('input-delay').value) || 0;
            const repeat = parseInt(document.getElementById('input-repeat').value) || 0;
            const max = repeat > 0 && hooks.repeatAllowed() ? parseInt(document.getElementById('input-max').value) || 1 : 1;

            document.getElementById('sum-delay').innerText = `${delay}m`;
            document.getElementById('sum-repeat').innerText = `${repeat}m`;
            document.getElementById('sum-max').innerText = `${max}x`;

            const totalMinutes = delay + (repeat * (max - 1));
            const hours = Math.floor(totalMinutes / 60);
            const mins = totalMinutes % 60;
            const timeSpanStr = hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;

            document.getElementById('schedule-span').innerText = `${delay}' ➔ ${timeSpanStr}`;
            document.getElementById('schedule-desc').innerText = `${max} notifications total over ${timeSpanStr}. Stops when resolved or dismissed.`;

            updateLivePreview();
        }

        function setSeverity(level) {
            currentSeverity = level;
            const btnInfo = document.getElementById('sev-info');
            const btnImp = document.getElementById('sev-important');
            const btnCrit = document.getElementById('sev-critical');
            const feedbackText = document.getElementById('sev-feedback-text');
            const accentBar = document.getElementById('preview-accent-bar');
            const iconBg = document.getElementById('preview-icon-bg');

            [btnInfo, btnImp, btnCrit].forEach(b => {
                b.className = "sev-btn py-1.5 rounded-lg text-[10px] font-medium text-gray-400 hover:text-gray-200 transition-all text-center";
            });

            if (level === 'info') {
                btnInfo.className = "sev-btn active py-1.5 rounded-lg text-[10px] font-bold bg-emerald-400 text-slate-950 shadow transition-all text-center";
                feedbackText.innerText = "Silent. Delivered quietly, no sound.";
                accentBar.className = "absolute left-0 top-0 bottom-0 w-1 bg-emerald-400";
                iconBg.className = "w-4 h-4 rounded-full bg-emerald-400 text-slate-950 flex items-center justify-center text-[9px] font-bold";
            } else if (level === 'important') {
                btnImp.className = "sev-btn active py-1.5 rounded-lg text-[10px] font-bold bg-emerald-400 text-slate-950 shadow transition-all text-center";
                feedbackText.innerText = "Plays a sound, high priority. Obeys quiet hours.";
                accentBar.className = "absolute left-0 top-0 bottom-0 w-1 bg-emerald-400";
                iconBg.className = "w-4 h-4 rounded-full bg-emerald-400 text-slate-950 flex items-center justify-center text-[9px] font-bold";
            } else if (level === 'critical') {
                btnCrit.className = "sev-btn active py-1.5 rounded-lg text-[10px] font-bold bg-rose-500 text-slate-950 shadow transition-all text-center";
                feedbackText.innerText = "Critical. Bypasses Do Not Disturb and mute.";
                accentBar.className = "absolute left-0 top-0 bottom-0 w-1 bg-rose-500";
                iconBg.className = "w-4 h-4 rounded-full bg-rose-500 text-slate-950 flex items-center justify-center text-[9px] font-bold";
            }
        }

        function setButtonOption(btn, option) {
            document.querySelectorAll('.btn-opt').forEach(b => {
                b.className = "btn-opt py-1.5 rounded-lg bg-[#1b1c20] border border-[#282a30] text-gray-400 text-center hover:text-gray-200 transition-all";
            });
            btn.className = "btn-opt active py-1.5 rounded-lg bg-emerald-400 text-slate-950 font-bold text-center shadow-md";
            
            const previewBtn = document.getElementById('preview-action-btn');
            const previewRow = document.getElementById('preview-action-row');

            if (option === 'None') {
                previewRow.classList.add('hidden');
            } else {
                previewRow.classList.remove('hidden');
                previewBtn.innerText = option;
            }
        }

        function insertVariable(varTag) {
            if (!lastFocusedInput) lastFocusedInput = document.getElementById('input-msg');
            const start = lastFocusedInput.selectionStart ?? lastFocusedInput.value.length;
            const end = lastFocusedInput.selectionEnd ?? lastFocusedInput.value.length;
            const text = lastFocusedInput.value;
            
            lastFocusedInput.value = text.substring(0, start) + varTag + text.substring(end);
            lastFocusedInput.focus();
            lastFocusedInput.setSelectionRange(start + varTag.length, start + varTag.length);
            updateLivePreview();
        }

        function updateLivePreview() {
            const rawTitle = document.getElementById('input-title').value;
            const rawMsg = document.getElementById('input-msg').value;
            const delay = document.getElementById('input-delay').value;

            let parsedTitle = rawTitle
                .replace(/{name}/g, String(hooks.values().name))
                .replace(/{battery}/g, String(hooks.values().battery))
                .replace(/{range}/g, String(hooks.values().range))
                .replace(/{minutes}/g, delay);

            let parsedMsg = rawMsg
                .replace(/{name}/g, String(hooks.values().name))
                .replace(/{battery}/g, String(hooks.values().battery))
                .replace(/{range}/g, String(hooks.values().range))
                .replace(/{minutes}/g, delay);

            document.getElementById('preview-title').innerText = parsedTitle || "Notification Title";
            document.getElementById('preview-body').innerText = parsedMsg || "Notification body message placeholder...";
        }

        function updateIcon(iconStr) {
            const pickerPreview = document.getElementById('icon-picker-preview');
            const headerIcon = document.getElementById('header-icon');
            const miniIcon = document.getElementById('preview-mini-icon');

            let faClass = "fa-solid fa-plug-circle-exclamation";
            if (iconStr.includes('battery')) faClass = "fa-solid fa-battery-three-quarters";
            if (iconStr.includes('car')) faClass = "fa-solid fa-car";
            if (iconStr.includes('lock')) faClass = "fa-solid fa-lock";

            pickerPreview.className = `${faClass} text-emerald-400 text-sm`;
            headerIcon.className = `${faClass} text-base`;
            miniIcon.className = faClass;
        }

        function toggleCardState(enabled) {
            const cardBody = document.getElementById('card-body');
            const statusBox = document.getElementById('status-icon-box');
            const statusLabel = document.getElementById('status-label');
            const statusDot = document.getElementById('status-dot');

            if (enabled) {
                cardBody.style.opacity = "1";
                cardBody.style.pointerEvents = "auto";
                statusBox.className = "w-10 h-10 rounded-full bg-emerald-400 text-slate-950 flex items-center justify-center shadow-lg emerald-glow shrink-0 transition-all";
                statusDot.className = "w-1.5 h-1.5 rounded-full bg-emerald-400";
                statusLabel.innerText = "Alert active";
                statusLabel.className = "text-emerald-400 font-medium";
            } else {
                cardBody.style.opacity = "0.4";
                cardBody.style.pointerEvents = "none";
                statusBox.className = "w-10 h-10 rounded-full bg-[#151619] border border-[#282a30] text-gray-500 flex items-center justify-center shrink-0 transition-all";
                statusDot.className = "w-1.5 h-1.5 rounded-full bg-gray-500";
                statusLabel.innerText = "Alert disabled";
                statusLabel.className = "text-gray-500 font-medium";
            }
        }

        function prototypeResetDefaults() {
            document.getElementById('input-delay').value = 30;
            document.getElementById('input-repeat').value = 60;
            document.getElementById('input-max').value = 2;
            document.getElementById('input-title').value = "{name} · Plugged in but not charging";
            document.getElementById('input-msg').value = "The plug has been in the port for {minutes} min without active charge.";
            setSeverity('important');
            updateCalculations();
            showToast("Reset to default vehicle configuration");
        }

        function prototypeSaveNotificationConfig() {
            showToast("Notification rules saved successfully!");
        }

        function showToast(msg) { if(hooks.silent())return;
            const toast = document.getElementById('toast');
            document.getElementById('toast-text').innerText = msg;
            toast.classList.remove('translate-y-20', 'opacity-0');
            setTimeout(() => {
                toast.classList.add('translate-y-20', 'opacity-0');
            }, 2200);
        }

        window.onload = function() {
            updateCalculations();
        };
    
function resetDefaults(){return hooks.reset();}
function saveNotificationConfig(){return hooks.save();}

return {switchView,toggleMasterNotifications,toggleDevicePill,toggleQuietHours,setQuietMode,filterPresets,adjustValue,updateCalculations,setSeverity,setButtonOption,insertVariable,updateLivePreview,updateIcon,toggleCardState,resetDefaults,saveNotificationConfig,showToast,remember:input=>{lastFocusedInput=input;},destroy:()=>clearTimeout(toastTimer)};
}